function buscaBinaria(arr, alvo) {
  let ini = 0, fim = arr.length - 1
  while (ini <= fim) {
    const meio = Math.floor((ini + fim) / 2)
    if (arr[meio] === alvo) return meio
    if (arr[meio] < alvo) ini = meio + 1
    else fim = meio - 1
  }
  return -1
}

function buscaLinear(arr, alvo) {
  for (let i = 0; i < arr.length; i++) {
    if (arr[i] === alvo) return i
  }
  return -1
}

function bubbleSort(arr) {
  for (let i = 0; i < arr.length; i++) {
    for (let j = 0; j < arr.length - i - 1; j++) {
      if (arr[j] > arr[j + 1]) [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]]
    }
  }
  return arr
}

function quickSort(arr) {
  if (arr.length <= 1) return arr
  const [pivo, ...resto] = arr
  const menores = resto.filter((n) => n < pivo)
  const maiores = resto.filter((n) => n >= pivo)
  return [...quickSort(menores), pivo, ...quickSort(maiores)]
}

function mergeSort(arr) {
  if (arr.length <= 1) return arr
  const meio = Math.floor(arr.length / 2)
  const esquerda = mergeSort(arr.slice(0, meio))
  const direita = mergeSort(arr.slice(meio))
  return merge(esquerda, direita)
}

function bfs(grafo, inicio) {
  const visitados = new Set([inicio])
  const fila = [inicio]
  const ordem = []
  while (fila.length) {
    const atual = fila.shift()
    ordem.push(atual)
    for (const vizinho of grafo[atual]) {
      if (!visitados.has(vizinho)) {
        visitados.add(vizinho)
        fila.push(vizinho)
      }
    }
  }
  return ordem
}

function dfs(grafo, atual, visitados = new Set()) {
  visitados.add(atual)
  for (const vizinho of grafo[atual]) {
    if (!visitados.has(vizinho)) dfs(grafo, vizinho, visitados)
  }
  return visitados
}

