function fatorial(n) {
  if (n <= 1) return 1 // caso base
  return n * fatorial(n - 1) // chamada recursiva
}

// Memoization (top-down)
function fib(n, cache = {}) {
  if (n in cache) return cache[n]
  if (n <= 1) return n
  return cache[n] = fib(n - 1, cache) + fib(n - 2, cache)
}

