function inserir(raiz, valor) {
  if (!raiz) return new NoBST(valor)
  if (valor < raiz.valor) raiz.esquerda = inserir(raiz.esquerda, valor)
  else raiz.direita = inserir(raiz.direita, valor)
  return raiz
}

function temParSoma(arr, alvo) {
  let esq = 0, dir = arr.length - 1
  while (esq < dir) {
    const soma = arr[esq] + arr[dir]
    if (soma === alvo) return true
    if (soma < alvo) esq++
    else dir--
  }
  return false
}

function maiorSomaSubarray(arr, k) {
  let somaJanela = arr.slice(0, k).reduce((a, b) => a + b, 0)
  let maiorSoma = somaJanela
  for (let i = k; i < arr.length; i++) {
    somaJanela += arr[i] - arr[i - k]
    maiorSoma = Math.max(maiorSoma, somaJanela)
  }
  return maiorSoma
}

